nta.declaration:
const int n = 6;
int[0,20] grid[n][n];

clock total_time;

//const int FORWARD = 0;
//const int BACKWARD = 1;
//const int ANY = 2;

bool canMove(int id, int x, int y, int dx, int dy, int len, bool horiz) {

    if (horiz) {
        int nextX = (dx > 0) ? x + len : x - 1;
        return nextX >= 0 && nextX < n && grid[y][nextX] == 0;

    } else {
        int nextY = (dy > 0) ? y + len : y - 1;
        return nextY >= 0 && nextY < n && grid[nextY][x] == 0;
    }
}

void place_car(int id, int x, int y, int len, bool horiz) {
    int i;
    for (i = 0; i < len; i++) {
        if (horiz) grid[y][x + i] = id;
        else       grid[y + i][x] = id;
    }
}

